WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY launch_date DESC, id) AS dedup_rank FROM products QUALIFY dedup_rank = 1) SELECT CASE WHEN price >= 1010 THEN 'HIGH' ELSE 'LOW' END AS price_tier, COUNT(*) AS cnt, SUM(CASE WHEN category = 'Home' THEN cost ELSE 0 END) AS home_cost FROM ranked GROUP BY CUBE (CASE WHEN price >= 1010 THEN 'HIGH' ELSE 'LOW' END) ORDER BY cnt NULLS FIRST;
